import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    n = int(input_data[0])
    m = int(input_data[1])

    strings = []
    idx = 2
    for _ in range(n):
        strings.append(input_data[idx])
        idx += 1

    def get_key(s):
        key = []
        for i, char in enumerate(s):
            if (i + 1) % 2 == 1:
                key.append(char)
            else:
                key.append(chr(255 - ord(char)))
        return tuple(key)

    indexed_strings = [(get_key(s), i + 1) for i, s in enumerate(strings)]
    indexed_strings.sort(key=lambda x: x[0])

    result = [str(item[1]) for item in indexed_strings]
    print(" ".join(result))

solve()
